'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()

  // Get current preference from cookie (default to 'off')
  const currentPreference = cookieStore.get('notifications')?.value || 'off'

  // Toggle the preference
  const newPreference = currentPreference === 'on' ? 'off' : 'on'

  // Save the new preference
  cookieStore.set('notifications', newPreference)

  // Refresh the current page to show updated preference
  refresh()

  return newPreference
}

